From 7dd57d7a6350770dfc283287125c409e995200e0 Mon Sep 17 00:00:00 2001
From: Karol Wachowski <karol.wachowski@linux.intel.com>
Date: Thu, 30 Apr 2026 11:56:44 +0200
Subject: [PATCH] accel/ivpu: Disallow re-exporting imported GEM objects

Prevent re-exporting of imported GEM buffers by adding a custom
prime_handle_to_fd callback that checks if the object is imported
and returns -EOPNOTSUPP if so.

Re-exporting imported GEM buffers causes loss of buffer flags settings,
leading to incorrect device access and data corruption.

Reported-by: Yametsu <yam3tsu@gmail.com>
Fixes: 57557964b582 ("accel/ivpu: Add support for userptr buffer objects")
Reviewed-by: Andrzej Kacprowski <andrzej.kacprowski@linux.intel.com>
Signed-off-by: Karol Wachowski <karol.wachowski@linux.intel.com>
Cc: <stable@vger.kernel.org> # v6.19+

diff --git a/drivers/accel/ivpu/ivpu_drv.c b/drivers/accel/ivpu/ivpu_drv.c
index 2801378e3e19..3b7b008bccfe 100644
--- a/drivers/accel/ivpu/ivpu_drv.c
+++ b/drivers/accel/ivpu/ivpu_drv.c
@@ -537,6 +537,26 @@ static const struct file_operations ivpu_fops = {
 #endif
 };

+static int ivpu_gem_prime_handle_to_fd(struct drm_device *dev, struct drm_file *file_priv,
+				       u32 handle, u32 flags, int *prime_fd)
+{
+	struct drm_gem_object *obj;
+
+	obj = drm_gem_object_lookup(file_priv, handle);
+	if (!obj)
+		return -ENOENT;
+
+	if (drm_gem_is_imported(obj)) {
+		/* Do not allow re-exporting */
+		drm_gem_object_put(obj);
+		return -EOPNOTSUPP;
+	}
+
+	drm_gem_object_put(obj);
+
+	return drm_gem_prime_handle_to_fd(dev, file_priv, handle, flags, prime_fd);
+}
+
 static const struct drm_driver driver = {
 	.driver_features = DRIVER_GEM | DRIVER_COMPUTE_ACCEL,

@@ -545,6 +565,7 @@ static const struct drm_driver driver = {

 	.gem_create_object = ivpu_gem_create_object,
 	.gem_prime_import = ivpu_gem_prime_import,
+	.prime_handle_to_fd = ivpu_gem_prime_handle_to_fd,

 	.ioctls = ivpu_drm_ioctls,
 	.num_ioctls = ARRAY_SIZE(ivpu_drm_ioctls),
-- 
2.34.1

The code statements that lead to the bug are:
```
static const struct drm_driver driver = {
	...
	.gem_prime_import = ivpu_gem_prime_import,
	/* Missing: .prime_handle_to_fd = ... */
};
```
Reason:
Without a custom `prime_handle_to_fd` callback, the default `drm_gem_prime_handle_to_fd` is used, which does not check whether a GEM object was imported. This allows re‑exporting imported buffers, causing loss of buffer flags and subsequent incorrect device access/data corruption.

The code statements that fix the bug are:
```
static int ivpu_gem_prime_handle_to_fd(struct drm_device *dev, struct drm_file *file_priv,
				       u32 handle, u32 flags, int *prime_fd)
{
	struct drm_gem_object *obj;

	obj = drm_gem_object_lookup(file_priv, handle);
	if (!obj)
		return -ENOENT;

	if (drm_gem_is_imported(obj)) {
		/* Do not allow re-exporting */
		drm_gem_object_put(obj);
		return -EOPNOTSUPP;
	}

	drm_gem_object_put(obj);

	return drm_gem_prime_handle_to_fd(dev, file_priv, handle, flags, prime_fd);
}
```
```
	.prime_handle_to_fd = ivpu_gem_prime_handle_to_fd,
```
Reason:
The new callback explicitly checks `drm_gem_is_imported(obj)` before proceeding. If the object was imported, it returns `-EOPNOTSUPP`, preventing re‑export. This preserves the original buffer flags and avoids the corruption caused by re‑exporting imported buffers. The assignment installs this callback in the driver, overriding the default behavior.

